const $=s=>document.querySelector(s),sim=new Simulation(),matrix=comparison(),measurements=shortcutMeasurements();let routeKey='',liveRoute=null;let view=null,selected='R1',planPreview=null,mapView='floors',lastUI=0,keys=new Set(),dragging=false,lastPointer=null;
if(['localhost','127.0.0.1'].includes(location.hostname))document.querySelectorAll('[data-hosted-source]').forEach(a=>a.hidden=true);
function makeView(){view?.dispose();try{view=new View($('#viewport'),sim);$('#webgl-error').hidden=true;}catch(error){view=null;$('#webgl-error').hidden=false;console.error('WebGL initialization failed',error);}const upper=sim.levels[1];$('#floor-select').innerHTML=`<option value="all">全層・搬送空間</option><option value="${upper}">第三層を切断表示</option><option value="0">第二層を切断表示</option>`;setView('overview');}
function setView(mode){view?.setMode(mode);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode));$('#crosshair').hidden=mode!=='explore';$('.touch-controls').classList.toggle('active',mode==='explore'&&matchMedia('(pointer:coarse)').matches);$('#camera-caption').textContent=mode==='overview'?'STAGE 03 / DEVELOPER CUTAWAY':'FIRST PERSON / MOVING CORRIDORS';$('#scene-title').textContent=mode==='overview'?'廊下を含む建築を、限られた空間で搬送する':'可動廊下を歩いて、個室・店舗・広間へ';$('#view-hint').textContent=mode==='overview'?'ドラッグで回転 · ホイールで拡大縮小':'WASD 移動 · ← → 回転 · ドラッグで視線 · E 操作';}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
$('#floor-select').onchange=e=>{if(view){view.floor=e.target.value;view.jointKey='';view.orbit.target.set(15,view.floor==='all'?8:Number(view.floor)+.5,11);view.orbit.distance=view.floor==='all'?66:49;view.orbit.pitch=view.floor==='all'?.72:1.05;}};
