$('#start').onclick=()=>{planPreview=null;sim.startTransfer();renderUI();};$('#pause').onclick=()=>{sim.paused=!sim.paused;renderUI();};$('#cancel').onclick=()=>{sim.cancelWarning();renderUI();};$('#speed').onchange=e=>sim.speed=Number(e.target.value);
function reset(e=sim.experiment){routeKey='';const experimental=$('#experimental').checked,speed=Number($('#speed').value);sim.reset(e);sim.experimental=experimental;sim.speed=speed;planPreview=null;keys.clear();makeView();renderUI();}
$('#reset').onclick=()=>reset();$('#apply-experiment').onclick=()=>reset({size:$('#experiment-size').value,method:$('#experiment-method').value});
$('#experimental').onchange=e=>{sim.experimental=e.target.checked;sim.message=e.target.checked?'意図的な孤立を許可。次周期で再接続する区画に残れます。':'通常の退避待ち・入場制限を有効にしました。';};
$('#rescue').onclick=()=>sim.rescue();$('#lift-button').onclick=()=>sim.useLift();$('#touch-e').onclick=()=>sim.interact();$('#help-button').onclick=()=>$('#help').showModal();$('#help-close').onclick=()=>$('#help').close();
$('#help').onclick=e=>{if(e.target===$('#help')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{mapView=b.dataset.map;document.querySelectorAll('[data-map]').forEach(q=>q.classList.toggle('active',q===b));$('#map-floors').hidden=mapView!=='floors';$('#map-deck').hidden=mapView!=='deck';renderUI();});
document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{planPreview=b.dataset.plan==='live'?null:b.dataset.plan;renderUI();});document.querySelectorAll('.map').forEach(m=>m.onclick=e=>{const b=e.target.closest('[data-id]');if(b){selected=b.dataset.id;renderUI();}});
const vp=$('#viewport');vp.addEventListener('pointerdown',e=>{if(e.target.tagName!=='CANVAS'||!view)return;dragging=true;lastPointer={x:e.clientX,y:e.clientY};e.target.setPointerCapture(e.pointerId);e.target.focus();});vp.addEventListener('pointermove',e=>{if(!dragging||!lastPointer||!view)return;const dx=e.clientX-lastPointer.x,dy=e.clientY-lastPointer.y;if(view.mode==='overview'){view.orbit.yaw-=dx*.008;view.orbit.pitch=Math.max(.15,Math.min(1.5,view.orbit.pitch+dy*.006));}else{sim.player.yaw-=dx*.004;sim.player.pitch=Math.max(-1.2,Math.min(1.2,sim.player.pitch-dy*.004));}lastPointer={x:e.clientX,y:e.clientY};});for(const ev of['pointerup','pointercancel'])vp.addEventListener(ev,()=>{dragging=false;lastPointer=null;});vp.addEventListener('wheel',e=>{if(view?.mode==='overview'){e.preventDefault();view.orbit.distance=Math.max(18,Math.min(145,view.orbit.distance+e.deltaY*.045));}},{passive:false});
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(e.target.tagName)||$('#help').open)return;if(['KeyW','KeyS','KeyA','KeyD','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyE','Space','ShiftLeft','ShiftRight'].includes(e.code)){e.preventDefault();keys.add(e.code);if(e.code==='KeyE'&&!e.repeat)sim.interact();}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
const touchKeys={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'};document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(touchKeys[b.dataset.move]);};b.onpointerup=b.onpointercancel=()=>keys.delete(touchKeys[b.dataset.move]);});
$('#comparison-results').innerHTML='<div class="comparison-scroll"><table><thead><tr><th>範囲 / 方式</th><th>面積比</th><th>高さ</th><th>循環秒</th><th>同時</th></tr></thead><tbody>'+matrix.map(r=>{const t=r.transitions;return `<tr data-profile="${r.size}-${r.method}"><td>${SIZES[r.size].label}<br>${METHODS[r.method]}</td><td>${t[0].areaRatio.toFixed(2)}×</td><td>${t[0].height.toFixed(1)}m<br>${t[0].decks}デッキ</td><td>${t.every(t=>t.ok)?t.reduce((s,t)=>s+t.duration,0).toFixed(1):'不成立'}</td><td>${Math.max(...t.map(t=>t.maxConcurrent))}体</td></tr>`;}).join('')+'</tbody></table></div><p>同一の建築と目標XY配置を使用。全案の生活階配置は共通。予備C0の保管位置は同程度案のみ内側。時間は1倍速・警告と開閉を除く。面積比は3周期共通の生活域外接矩形を基準。</p>';
function renderUI(){const active=sim.mode!=='idle',own=sim.owner,level=Math.abs(sim.player.y-sim.levels[1])<.1?'第三層':Math.abs(sim.player.y)<.1?'第二層':'搬送空間',row=matrix.find(r=>r.size===sim.experiment.size&&r.method===sim.experiment.method),bound=SIZES[sim.experiment.size];
 $('#phase-badge').textContent=`周期 ${sim.phase}`;$('#phase-description').textContent=PHASES[sim.phase].label;$('#reachable-count').innerHTML=`${new Set([...sim.liveReachable].filter(n=>n.includes('/')).map(n=>n.split('/')[0])).size}<span>/ ${BODIES.filter(b=>sim.levels.includes(sim.positions[b.id].y)).length}</span>`;$('#collision-count').textContent=sim.lastCheck?.errors.length??0;$('#max-concurrent').textContent=Math.max(...row.transitions.map(t=>t.maxConcurrent));$('#player-location').textContent=`${level} / ${BY_ID[own]?.name??(own==='lift'?'固定EV':own?.startsWith('joint:')?'格納式継手':'固定EV乗場')}`;$('#coordinates').textContent=`X ${sim.player.x.toFixed(1)}　Y ${sim.player.y.toFixed(1)}　Z ${sim.player.z.toFixed(1)}`;$('#message').textContent=sim.message;
 $('#scene-subtitle').textContent=`外形 8 × 8 × 6m ／ 搬送域 ${bound.w} × ${bound.d}m ／ 離隔 ≥0.2m`;$('#experiment-summary').textContent=`採用中：${bound.label}・${METHODS[sim.experiment.method]} ／ 面積 ${row.transitions[0].areaRatio.toFixed(2)}倍・上端 ${row.transitions[0].height.toFixed(1)}m`;
 $('#sequence').innerHTML=`${active?sim.plan?.from??sim.phase:sim.phase} <i>→</i> ${active?sim.plan?.to??sim.next:sim.next}`;$('#start').disabled=active||sim.liftActive;$('#start').innerHTML=`${sim.next} へ搬送 <span>→</span>`;$('#pause').disabled=!active&&!sim.liftActive;$('#pause').textContent=sim.paused?'▶':'Ⅱ';$('#pause').title=sim.paused?'再開':'一時停止';$('#cancel').hidden=!['warning','evacuate'].includes(sim.mode);$('#apply-experiment').disabled=active||sim.liftActive;$('#experiment-size').disabled=active;$('#experiment-method').disabled=active;
 const statuses={idle:'ドック固定・可動廊下を探索可能',warning:`退避警告 ${Math.max(0,5-sim.elapsed).toFixed(1)}秒`,evacuate:'退避・継手の安全確認待ち',closing:'シャッター閉鎖・継手を格納',moving:'搬送中・探索操作停止',opening:'着床・継手展開・開放'};$('#transfer-status').textContent=(sim.paused?'一時停止 / ':'')+statuses[sim.mode];const st=sim.plan?.stages[sim.stageIndex];$('#stage-label').textContent=sim.mode==='moving'?`${sim.stageIndex+1}/${sim.plan.stages.length}　${st?.label??'到着確認'}`:'空いた位置を順に再利用する搬送計画';$('#progress').style.width=`${Math.min(100,(sim.mode==='moving'?sim.elapsed/sim.plan.duration:sim.mode==='opening'?1:0)*100)}%`;
 document.querySelectorAll('[data-plan]').forEach(b=>b.classList.toggle('active',b.dataset.plan===(planPreview??'live')));const rk=sim.phase+JSON.stringify(sim.doors);if(rk!==routeKey&&sim.mode==='idle'){routeKey=rk;liveRoute=shortestWalk(sim,sim.referencePoint('home'),sim.referencePoint('shop'));}view?.setWalkPath(sim.mode==='idle'?liveRoute:null,sim.phase);const route=planPreview?measurements.rows.find(r=>r.phase===planPreview).route:sim.mode==='idle'?liveRoute:null;$('#map-upper').innerHTML=floorSVG(sim,1,{phase:planPreview,selected,path:route});$('#map-lower').innerHTML=floorSVG(sim,0,{phase:planPreview,selected});if(mapView==='deck')$('#map-deck').innerHTML=deckSVG(sim);$('#upper-height').textContent=`床高 +${sim.levels[1]}m`;$('#map-note').textContent=planPreview?`配置計画 ${planPreview}。3Dの実配置は周期 ${sim.phase}。`:sim.mode==='moving'?'搬送デッキで現在位置・高さ・現在区間の掃引を確認。':'空欄は搬送井で床なし。緑の継手を通り、可動廊下から各区域へ。';
 const b=BY_ID[selected],f=footprint(b),links=(planPreview?connections(planPreview,sim.experiment):sim.liveConnections).filter(c=>c.bodyA===b.id||c.bodyB===b.id);$('#selected-id').textContent=b.id;$('#selected-name').textContent=b.name;$('#selected-size').textContent=`${b.cells.length}チャンク / ${f.w} × ${f.d} × ${HEIGHT}m 外形`;
 const ps=(planPreview?portStates(planPreview,sim.experiment,defaultDoors()):sim.livePorts).filter(p=>p.body===b.id);$('#selected-detail').innerHTML=`<b>室内高 ${Math.min(...b.roofAreas.map(r=>r.height)).toFixed(2)}〜${b.ceiling.toFixed(2)}m ／ 独立通路 ${localNavigation(b,sim.doors).components.length}</b><br>${ps.map(p=>`${p.id} (${p.face})：${p.status==='pass'?'通行可／開':p.status==='view'?'視認のみ／部分開':'遮断／閉'}<br><small>${p.node??'内部不連続'} ／ 幅 ${(p.b-p.a).toFixed(2)} × 高 ${p.height.toFixed(2)}m${p.matches.map(c=>' → '+(c.bodyA===b.id?c.bodyB+':'+c.portB:c.bodyA+':'+c.portA)+' 重なり'+c.width.toFixed(2)+'m').join('')}</small>`).join('<br>')}<br>${isolated(planPreview??sim.phase,sim.experiment).includes(b.id)?'<b>EV乗場から孤立。次周期で再接続。</b>':''}`;
 $('#validation-results').innerHTML=row.transitions.map(v=>`<p>${v.from}→${v.to}：${v.ok?'離隔違反0':'不成立'} / ${v.stages}区間 / ${v.checks}検査 / ${v.duration.toFixed(1)}秒</p>`).join('');$('#history').innerHTML=sim.history.length?sim.history.map(x=>`<p>${x}</p>`).join(''):'搬送記録はまだありません。';document.querySelectorAll('[data-profile]').forEach(r=>r.classList.toggle('current-profile',r.dataset.profile===sim.experiment.size+'-'+sim.experiment.method));
}
$('#shortcut-results').innerHTML=measurements.rows.map(r=>`<span><b>${r.phase} ${r.route.distance.toFixed(2)}m</b>　環状 ${r.cycles[1].cycles}</span>`).join('<br>')+`<p>C0挿入で ${(measurements.reductionRatio*100).toFixed(1)}% 短縮。同じ住戸301→生活用品店。0.2m格子・身体幅込みの最短経路。線を3Dでも追えます。</p>`;
makeView();renderUI();let last=performance.now();function frame(t){const dt=Math.min(.1,(t-last)/1000);last=t;if(view?.mode==='explore'&&!$('#help').open){const forward=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),side=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0);if(['idle','warning','evacuate'].includes(sim.mode)&&!sim.liftActive){sim.player.yaw+=(keys.has('ArrowLeft')?1:0)*dt*1.7-(keys.has('ArrowRight')?1:0)*dt*1.7;sim.walk(forward,side,dt,keys.has('ShiftLeft')||keys.has('ShiftRight'));}}sim.tick(dt);view?.render();if(t-lastUI>120){renderUI();lastUI=t;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.lab={sim,get view(){return view;},setView,matrix,measurements,snapshot:()=>({phase:sim.phase,mode:sim.mode,experiment:{...sim.experiment},positions:structuredClone(sim.positions),player:{...sim.player},webgl:!!view})};
